from collections import Counter


class Solution:
    def recoverArray(self, n: int, sums: List[int]) -> List[int]:
        def split(cur, d):
            cnt = Counter(cur)
            lower = []
            for v in cur:
                if cnt[v] <= 0:
                    continue
                cnt[v] -= 1
                if cnt[v + d] <= 0:
                    return None
                cnt[v + d] -= 1
                lower.append(v)
            return lower

        def solve(cur):
            if len(cur) == 1:
                return []
            vals = sorted(set(cur))
            gaps = sorted({b - a for a in vals for b in vals if b > a})
            if len(vals) < len(cur):
                gaps = [0] + gaps
            for d in gaps:
                lower = split(cur, d)
                if lower is None:
                    continue
                upper = [v + d for v in lower]
                for half, x in ((lower, d), (upper, -d)):
                    if 0 in half:
                        sub = solve(half)
                        if sub is not None:
                            return sub + [x]
            return None

        return solve(sorted(sums))

