class Solution {
    bool split(vector<int>& cur, long long d, vector<int>& lower) {
        map<long long, int> cnt;
        for (int v : cur) cnt[v]++;
        for (int v : cur) {
            if (cnt[v] <= 0) continue;
            cnt[v]--;
            if (cnt[v + d] <= 0) return false;
            cnt[v + d]--;
            lower.push_back(v);
        }
        return true;
    }

    static bool hasZero(vector<int>& v) {
        return binary_search(v.begin(), v.end(), 0);
    }

    bool solve(vector<int>& cur, vector<int>& out) {
        if (cur.size() == 1) return true;
        vector<int> uniq = cur;
        uniq.erase(unique(uniq.begin(), uniq.end()), uniq.end());
        set<long long> gaps;
        for (size_t i = 0; i < uniq.size(); ++i)
            for (size_t j = i + 1; j < uniq.size(); ++j)
                gaps.insert((long long)uniq[j] - uniq[i]);
        if (uniq.size() < cur.size()) gaps.insert(0);
        vector<int> sub;
        for (long long d : gaps) {
            vector<int> lower, upper;
            if (!split(cur, d, lower)) continue;
            for (int v : lower) upper.push_back(v + (int)d);
            if (hasZero(lower) && solve(lower, sub)) {
                out = sub;
                out.push_back((int)d);
                return true;
            }
            if (hasZero(upper) && solve(upper, sub)) {
                out = sub;
                out.push_back(-(int)d);
                return true;
            }
        }
        return false;
    }

public:
    vector<int> recoverArray(int n, vector<int>& sums) {
        sort(sums.begin(), sums.end());
        vector<int> ans;
        solve(sums, ans);
        return ans;
    }
};

