class Solution {
    private List<Integer> split(List<Integer> cur, long d) {
        Map<Long, Integer> cnt = new HashMap<>();
        for (int v : cur) cnt.merge((long) v, 1, Integer::sum);
        List<Integer> lower = new ArrayList<>();
        for (int v : cur) {
            if (cnt.getOrDefault((long) v, 0) <= 0) continue;
            cnt.merge((long) v, -1, Integer::sum);
            if (cnt.getOrDefault((long) v + d, 0) <= 0) return null;
            cnt.merge((long) v + d, -1, Integer::sum);
            lower.add(v);
        }
        return lower;
    }

    private boolean hasZero(List<Integer> v) {
        int lo = 0, hi = v.size() - 1;
        while (lo <= hi) {
            int mid = (lo + hi) >>> 1;
            if (v.get(mid) == 0) return true;
            if (v.get(mid) < 0) lo = mid + 1;
            else hi = mid - 1;
        }
        return false;
    }

    private boolean solve(List<Integer> cur, List<Integer> out) {
        if (cur.size() == 1) return true;
        TreeSet<Long> gaps = new TreeSet<>();
        for (int i = 0; i < cur.size(); ++i)
            for (int j = i + 1; j < cur.size(); ++j)
                gaps.add((long) cur.get(j) - cur.get(i));
        List<Integer> sub = new ArrayList<>();
        for (long d : gaps) {
            List<Integer> lower = split(cur, d);
            if (lower == null) continue;
            List<Integer> upper = new ArrayList<>();
            for (int v : lower) upper.add(v + (int) d);
            if (hasZero(lower) && solve(lower, sub)) {
                sub.add((int) d);
                out.addAll(sub);
                return true;
            }
            if (hasZero(upper) && solve(upper, sub)) {
                sub.add(-(int) d);
                out.addAll(sub);
                return true;
            }
        }
        return false;
    }

    public int[] recoverArray(int n, int[] sums) {
        List<Integer> cur = new ArrayList<>();
        for (int v : sums) cur.add(v);
        Collections.sort(cur);
        List<Integer> res = new ArrayList<>();
        solve(cur, res);
        int[] ans = new int[res.size()];
        for (int i = 0; i < res.size(); i++) ans[i] = res.get(i);
        return ans;
    }
}

